# Surah Al-Baqarah (chapter 2) — part 17: ayat 161-170 (IDs 168-177)
SURAH = 2

ENTRIES = {
168: (
"بے شک جن لوگوں نے کفر کیا اور اس حال میں مرے کہ وہ کافر تھے — یہی لوگ ہیں جن پر اللہ کی، فرشتوں کی اور سب لوگوں کی لعنت ہے۔",
"""۱۔ کفر پر مرنے والوں کا انجام — اللہ اور تمام مخلوق کی لعنت۔
۲۔ ’’إِنَّ الَّذِينَ كَفَرُوا وَمَاتُوا وَهُمْ كُفَّارٌ‘‘ — بے شک جن لوگوں نے کفر کیا اور اس حال میں مرے کہ وہ کافر تھے — یعنی بغیر توبہ کے زندگی چھوڑنا۔
۳۔ ’’أُولَٰئِكَ عَلَيْهِمْ لَعْنَةُ اللّٰہِ وَالْمَلَائِكَۃِ وَالنَّاسِ أَجْمَعِينَ‘‘ — یہی لوگ ہیں جن پر اللہ کی، فرشتوں کی اور سب لوگوں کی لعنت ہے — یعنی دائمی لعنت اور دوریِ رحمت۔
۴۔ کفر پر موت کا مطلب ہے جان بوجھ کر حق کا انکار کرتے ہوئے زندگی ختم کرنا — یہ سنگین ترین جرم ہے۔
۵۔ عملی سبق: دل میں کبھی بھی حق کے انکار کا ارادہ نہ لائیں — مرتے وقت ایمان کی حالت ہی آخری فیصلہ ہے۔"""
),
169: (
"وہ اس میں ہمیشہ رہنے والے ہیں — نہ ان سے عذاب ہلکا کیا جائے گا اور نہ انہیں مہلت دی جائے گی۔",
"""۱۔ کافروں کا عذاب بیان ہو رہا ہے — دائمی اور بغیر کمی۔
۲۔ ’’خَالِدِينَ فِيهَا‘‘ — وہ اس میں ہمیشہ رہنے والے ہیں — یعنی جہنم میں ابدی ٹھکانا۔
۳۔ ’’لَا يُخَفَّفُ عَنْهُمُ الْعَذَابُ وَلَا هُمْ يُنظَرُونَ‘‘ — نہ ان سے عذاب ہلکا کیا جائے گا اور نہ انہیں مہلت دی جائے گی — یعنی نہ تخفیف نہ تاخیر۔
۴۔ یہ آیت دل دہلانے والی ہے — اللہ کی رحمت بہت وسیع ہے مگر جان بوجھ کر کفر کرنے والوں کے لیے یہ سزا بھی یقینی ہے۔
۵۔ عملی سبق: کفر اور شرک کا ارادہ ہر گز نہ کریں؛ مرتے دم تک ایمان پر قائم رہیں۔"""
),
170: (
"اور تمہارا معبود ایک معبود ہے — اس کے سوا کوئی معبود نہیں — وہ بڑا مہربان، نہایت رحم والا ہے۔",
"""۱۔ توحید کا سب سے جامع اور واضح جملہ — قرآن کا بنیادی کلمہ۔
۲۔ ’’وَإِلَٰهُكُمْ إِلَٰهٌ وَاحِدٌ‘‘ — اور تمہارا معبود ایک معبود ہے — یعنی صرف ایک اللہ ہے۔
۳۔ ’’لَّا إِلَٰهَ إِلَّا هُوَ‘‘ — اس کے سوا کوئی معبود نہیں — یعنی اللہ کے سوا کسی کی پرستش نہیں ہوسکتی۔
۴۔ ’’الرَّحْمَٰنُ الرَّحِيمُ‘‘ — وہ بڑا مہربان، نہایت رحم والا ہے — یعنی توحید کا اقرار رحمت کا دعویٰ بھی ہے؛ اللہ عبادت کے بھی لائق ہے اور رحمت بھی خود فرماتا ہے۔
۵۔ عملی سبق: اپنی زندگی میں اللہ کی عبادت کو اولین مقام دیں؛ کسی بھی چیز کو اس کے مقام پر نہ رکھیں۔"""
),
171: (
"بے شک آسمانوں اور زمین کے پیدا کرنے میں، رات اور دن کے فرق میں، ان کشتیوں میں جو سمندر میں چلتی ہیں لوگوں کے فائدے کے لیے، اور اس پانی میں جو اللہ نے آسمان سے اتارا اور اس سے زمین کو اس کی موت کے بعد زندہ کیا اور اس پر ہر قسم کے جاندار پھیلا دیے، اور ہواؤں کے پھیرنے اور ابر کے (درمیان میں) جو آسمان اور زمین کے درمیان معلق ہے — بے شک ان میں نشانیاں ہیں ان لوگوں کے لیے جو عقل رکھتے ہیں۔",
"""۱۔ توحید اور ربانیت کی دلائل بیان کی جا رہی ہیں — کائنات کی ہر چیز اللہ کی قدرت کی نشانی ہے۔
۲۔ ’’إِنَّ فِي خَلْقِ السَّمَاوَاتِ وَالْأَرْضِ‘‘ — آسمانوں اور زمین کے پیدا کرنے میں — یعنی ان کی تخلیق کا نظام اللہ کی حکمت کا شاہکار ہے۔
۳۔ ’’وَاخْتِلَافِ اللَّيْلِ وَالنَّهَارِ‘‘ — رات اور دن کے فرق میں — یعنی سورج کی گردش اور زندگی کے چکر کا انتظام۔
۴۔ ’’وَالْفُلْكِ الَّتِي تَجْرِي فِي الْبَحْرِ بِمَا يَنفَعُ النَّاسَ‘‘ — ان کشتیوں میں جو سمندر میں چلتی ہیں لوگوں کے فائدے کے لیے — یعنی تجارت اور نقل و حمل کے نظام کا اللہ کا انتظام۔
۵۔ ’’وَمَا أَنزَلَ اللّٰہُ مِنَ السَّمَاءِ مِن مَّاءٍ فَأَحْيَا بِهِ الْأَرْضَ بَعْدَ مَوْتِهَا‘‘ — اور اس پانی میں جو اللہ نے آسمان سے اتارا اور اس سے زمین کو اس کی موت کے بعد زندہ کیا — یعنی بارش اور نباتات اور زرخیزی۔
۶۔ ’’وَبَثَّ فِيهَا مِن كُلِّ دَابَّۃٍ‘‘ — اور اس پر ہر قسم کے جاندار پھیلا دیے — یعنی حیوانات کی متنوع اقسام۔
۷۔ ’’وَتَصْرِيفِ الرِّيَاحِ وَالسَّحَابِ الْمُسَخَّرِ بَيْنَ السَّمَاءِ وَالْأَرْضِ‘‘ — اور ہواؤں کے پھیرنے اور ابر کے (درمیان میں) جو آسمان اور زمین کے درمیان معلق ہے — یعنی موسمیات کا اللہ کا انتظام۔
۸۔ ’’لَآيَاتٍ لِّقَوْمٍ يَعْقِلُونَ‘‘ — بے شک ان میں نشانیاں ہیں ان لوگوں کے لیے جو عقل رکھتے ہیں — یعنی سوچنے والے کے لیے ہر چیز اللہ کی نشانی ہے۔
۹۔ عملی سبق: اپنی زندگی میں، کائنات میں اللہ کی قدرت کے مظاہر دیکھیں؛ عقل اور غور و فکر سے ایمان مضبوط ہوتا ہے۔"""
),
172: (
"اور انسانوں میں سے وہ لوگ ہیں جو اللہ کے سوا (اس کے) شریک بناتے ہیں ان سے محبت کرتے ہیں جیسی اللہ سے محبت — اور جو ایمان لائے وہ اللہ سے محبت میں سب سے بڑھ کر (شدید) ہیں — اور اگر وہ لوگ جنہوں نے ظلم کیا (عذاب) دیکھتے تو جانتے کہ پوری طاقت اللہ ہی کی ہے اور اللہ سخت عذاب والا ہے۔",
"""۱۔ مشرکین کی محبت بیان ہو رہی ہے — جو اللہ کے علاوہ کسی کو (بتوں یا بڑے لوگوں) اللہ کی طرح محبوب بناتے ہیں۔
۲۔ ’’وَمِنَ النَّاسِ مَن يَتَّخِذُ مِن دُونِ اللّٰہِ أَندَادًا يُحِبُّونَهُمْ كَحُبِّ اللّٰہِ‘‘ — اور انسانوں میں سے وہ لوگ ہیں جو اللہ کے سوا (اس کے) شریک بناتے ہیں ان سے محبت کرتے ہیں جیسی اللہ سے محبت — یعنی اللہ کے برابر کسی اور سے محبت رکھنا شرک ہے۔
۳۔ ’’وَالَّذِينَ آمَنُوا أَشَدُّ حُبًّا لِلّٰہِ‘‘ — اور جو ایمان لائے وہ اللہ سے محبت میں سب سے بڑھ کر (شدید) ہیں — یعنی مؤمنوں کی اللہ سے محبت سب سے مضبوط ہے۔
۴۔ ’’وَلَوْ يَرَى الَّذِينَ ظَلَمُوا إِذْ يَرَوْنَ الْعَذَابَ أَنَّ الْقُوَّۃَ لِلّٰہِ جَمِيعًا‘‘ — اور اگر وہ لوگ جنہوں نے ظلم کیا (عذاب) دیکھتے تو جانتے کہ پوری طاقت اللہ ہی کی ہے — یعنی قیامت میں ہر طاقت کا منبع صرف اللہ ہے۔
۵۔ ’’وَأَنَّ اللّٰہَ شَدِيدُ الْعَذَابِ‘‘ — اور اللہ سخت عذاب والا ہے۔
۶۔ عملی سبق: محبت کی ڈور صرف اللہ سے جوڑیں؛ کسی کی محبت اتنی نہ ہو کہ اللہ کی جگہ لے لے۔"""
),
173: (
"جب کہ وہ لوگ جن کی پیروی کی گئی (وہ) اپنے پیروکاروں سے بے زاری کا اعلان کریں گے اور عذاب دیکھیں گے — اور ان سے تمام (تعلقات کے) اسباب کٹ جائیں گے۔",
"""۱۔ قیامت میں مشرکین اور ان کے معبودوں کے درمیان مکمل لاتعلقی بیان ہو رہی ہے۔
۲۔ ’’إِذْ تَبَرَّأَ الَّذِينَ اتُّبِعُوا مِنَ الَّذِينَ اتَّبَعُوا‘‘ — جب کہ وہ لوگ جن کی پیروی کی گئی (وہ) اپنے پیروکاروں سے بے زاری کا اعلان کریں گے — یعنی مشرکین کے معبود یا رہنما تب بری ہو جائیں گے۔
۳۔ ’’وَرَأَوُا الْعَذَابَ‘‘ — اور عذاب دیکھیں گے — یعنی سامنے ہی آخرت کا عذاب ہوگا۔
۴۔ ’’وَتَقَطَّعَتْ بِهِمُ الْأَسْبَابُ‘‘ — اور ان سے تمام (تعلقات کے) اسباب کٹ جائیں گے — یعنی دنیا کے تمام رشتے اور تعلق قیامت میں کام نہیں آئیں گے۔
۵۔ عملی سبق: کسی بھی انسان کو اللہ کا درجہ نہ دیں؛ قیامت میں کوئی کسی کی مدافعت نہیں کرے گا۔"""
),
174: (
"اور پیروکار کہیں گے: اگر ہمیں ایک بار پھر (دنیا میں) جانے کا موقع ملتا تو ہم ان سے بالکل اسی طرح بے زاری کا اظہار کرتے جیسے انہوں نے ہم سے کیا — اسی طرح اللہ انہیں ان کے اعمال (ندامتوں کی صورت میں) دکھائے گا — اور وہ آگ سے نکلنے والے نہیں۔",
"""۱۔ قیامت میں پیروکاروں کی حسرت بیان ہو رہی ہے — وہ موقع ملنے پر واپس جا کر مکہنے والے لوگوں سے بے زاری کا اظہار کریں گے۔
۲۔ ’’لَوْ أَنَّ لَنَا كَرَّۃً فَنَتَبَرَّأَ مِنْهُمْ كَمَا تَبَرَّءُوا مِنَّا‘‘ — اگر ہمیں ایک بار پھر (دنیا میں) جانے کا موقع ملتا تو ہم ان سے بالکل اسی طرح بے زاری کا اظہار کرتے جیسے انہوں نے ہم سے کیا — یعنی پیچھے ہٹنے کی خواہش مگر موقع نہیں ملے گا۔
۳۔ ’’كَذَٰلِكَ يُرِيهِمُ اللّٰہُ أَعْمَالَهُمْ حَسَرَۃً‘‘ — اسی طرح اللہ انہیں ان کے اعمال (ندامتوں کی صورت میں) دکھائے گا — یعنی ان کے اعمال انہیں حسرت اور نقصان کا احساس دلائیں گے۔
۴۔ ’’وَمَا هُم بِخَارِجِينَ مِنَ النَّارِ‘‘ — اور وہ آگ سے نکلنے والے نہیں — یعنی جہنم میں ابدی رہیں گے۔
۵۔ عملی سبق: دنیا میں رہتے ہوئے اپنے اعمال درست کریں — قیامت پر ندامت کا کوئی فائدہ نہیں۔"""
),
175: (
"اے لوگو! زمین کی حلال اور پاکیزہ چیزیں کھاؤ — اور شیطان کے نقشِ قدم پر نہ چلو — بے شک وہ تمہارا کھلم کھلا دشمن ہے۔",
"""۱۔ حلال اور طیب رزق کھانے کا حکم — اور شیطان سے بچاؤ۔
۲۔ ’’كُلُوا مِمَّا فِي الْأَرْضِ حَلَالًا طَيِّبًا‘‘ — زمین کی حلال اور پاکیزہ چیزیں کھاؤ — یعنی رزق جو حلال ہو (اللہ کی حلال کردہ) اور طیب (پاکیزہ) ہو۔
۳۔ ’’وَلَا تَتَّبِعُوا خُطُوَاتِ الشَّيْطَانِ‘‘ — اور شیطان کے نقشِ قدم پر نہ چلو — یعنی شیطان جس راستے پر چلے اس سے بچو۔
۴۔ ’’إِنَّهُ لَكُمْ عَدُوٌّ مُّبِينٌ‘‘ — بے شک وہ تمہارا کھلم کھلا دشمن ہے — یعنی شیطان انسان کا کھلا دشمن ہے؛ کوئی چپکے چپکے کا معاملہ نہیں۔
۵۔ عملی سبق: کھانے پینے میں حلال اور طیب کا خیال رکھیں؛ شیطان کی فریب کاریوں سے بچیں۔"""
),
176: (
"بے شک وہ تمہیں صرف برائی اور بے حیائی کا حکم دیتا ہے اور اس کا کہ (تم) اللہ کے بارے میں وہ کہو جو تم نہیں جانتے۔",
"""۱۔ شیطان کی تین بنیادی اقسام بیان کی جا رہی ہیں — برائی، بے حیائی اور اللہ کے بارے میں بے بنیاد باتیں۔
۲۔ ’’إِنَّمَا يَأْمُرُكُم بِالسُّوءِ وَالْفَحْشَاءِ‘‘ — بے شک وہ تمہیں صرف برائی اور بے حیائی کا حکم دیتا ہے — یعنی شیطان صرف گناہ اور شہوت کا پرچار کرتا ہے۔
۳۔ ’’وَأَن تَقُولُوا عَلَى اللّٰہِ مَا لَا تَعْلَمُونَ‘‘ — اور اس کا کہ (تم) اللہ کے بارے میں وہ کہو جو تم نہیں جانتے — یعنی اللہ کے بارے میں جھوٹ بولنا — یہ بدترین قسم کا گناہ ہے۔
۴۔ شیطان انسان کو پہلے گناہ پر پھر دین کے بارے میں بے بنیاد فتوے دینے پر آمادہ کرتا ہے — یہی شیطان کا اصل ہتھیار ہے۔
۵۔ عملی سبق: شیطان کے وسوسوں سے ہوشیار رہیں؛ اللہ کے بارے میں لاعلمی سے بولنے سے بچا کریں۔"""
),
177: (
"اور جب ان سے کہا جاتا ہے: اللہ نے جو نازل کیا اس کی پیروی کرو — تو وہ کہتے ہیں: بلکہ ہم اس کی پیروی کریں گے جس پر ہم نے اپنے باپ دادا کو پایا — کیا اگرچہ ان کے باپ دادا نہ سمجھتے ہوں کچھ اور نہ ہدایت پاتے ہوں۔",
"""۱۔ مشرکین کا وہ طرز عمل بیان ہو رہا ہے — وراثتی اعمال کو دین سمجھ کر رکھنا۔
۲۔ ’’وَإِذَا قِيلَ لَهُمُ اتَّبِعُوا مَا أَنزَلَ اللّٰہُ‘‘ — اور جب ان سے کہا جاتا ہے: اللہ نے جو نازل کیا اس کی پیروی کرو — یعنی اللہ کی ہدایت کی طرف بلایا جائے۔
۳۔ ’’قَالُوا بَلْ نَتَّبِعُ مَا أَلْفَيْنَا عَلَيْهِ آبَاءَنَا‘‘ — تو وہ کہتے ہیں: بلکہ ہم اس کی پیروی کریں گے جس پر ہم نے اپنے باپ دادا کو پایا — یعنی آبائی طریقے کو دین سمجھنا۔
۴۔ ’’أَوَلَوْ كَانَ آبَاؤُهُمْ لَا يَعْقِلُونَ شَيْئًا وَلَا يَهْتَدُونَ‘‘ — کیا اگرچہ ان کے باپ دادا نہ سمجھتے ہوں کچھ اور نہ ہدایت پاتے ہوں — یعنی آبائی طریقہ عقل اور ہدایت سے خالی ہو تو بھی اس پر قائم رہنا؟
۵۔ یہ آیت ہر دور کے وہ لوگوں کے لیے ہے جو آبائی یا ثقافتی عادات کو دین سمجھ کر رکھتے ہیں۔
۶۔ عملی سبق: اپنی زندگی میں دین کو عقل اور ہدایت کی کسوٹی پر پرکھو؛ آبائی طریقہ صرف اس وقت رکھو جب وہ اللہ کی ہدایت کے مطابق ہو۔"""
),
}
